{
  "a_sentences": [
    {
      "a_text": "Le litige porte sur la question de savoir si la juridiction cantonale a violé le droit fédéral en niant à la personne assurée un droit à une rente de partenaire de vie à la charge de l'intimée.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "La prise en considération de personnes bénéficiaires au sens de l'art. 20a al. 1 LPP relève de la prévoyance professionnelle plus étendue.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Une institution de prévoyance peut subordonner l'octroi de prestations au sens de l'art. 20a LPP à une déclaration écrite de la personne assurée, constitutive de l'exigence formelle du droit.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "L'exigence d'une déclaration écrite de bénéficiaire ne constitue pas un simple formalisme, mais un instrument permettant à l'institution de prévoyance de s'assurer une clarté sur les bénéficiaires.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Contrairement aux droits obligatoires du conjoint ou du partenaire enregistré, la personne assurée dispose d'une liberté de choix quant à la désignation d'un partenaire de vie.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Les institutions de prévoyance sont libres de déterminer si elles prévoient des prestations pour les personnes visées par l'art. 20a al. 1 LPP.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le droit à la protection de la bonne foi suppose cumulativement une information sans réserve des autorités, concernant une affaire concrète, émanant d'une instance compétente ou apparaissant comme telle, dont l'inexactitude n'était pas reconnaissable et qui a conduit à des dispositions irrévocables sans préjudice.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "En l'espèce, il n'existait pas de fondement suffisant pour admettre, de bonne foi, un droit à une rente de partenaire de vie simplement sur la base de la formulation du certificat de prévoyance.",
      "b_propositions": ["P8"]
    }
  ]
}
